**S1:** *Create a decorator that logs function arguments and return value.*
```python
def log(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__}(args={args}, kwargs={kwargs})")
        result = func(*args, **kwargs)
        print(f"{func.__name__} returned {result}")
        return result
    return wrapper
```

**S2:** *Create a rate-limiter decorator that allows max N calls per minute.*
```python
def rate_limit(max_calls: int, period: float = 60):
    calls = []
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            now = time.time()
            calls[:] = [t for t in calls if now - t < period]
            if len(calls) >= max_calls:
                raise Exception("Rate limit exceeded")
            calls.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator
```

**S3:** *Create a decorator that enforces type checking on function arguments.*
```python
def type_check(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        hints = func.__annotations__
        # Validate using hints...
        return func(*args, **kwargs)
    return wrapper
```

**S4:** *How would you make a decorator that works both with and without parentheses?*
```python
def smart_decorator(_func=None, *, param="default"):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper
    if _func is not None:
        return decorator(_func)  # Called without ()
    return decorator              # Called with ()
```

**S5:** *Design an authentication decorator for a web API.*
```python
def require_auth(func):
    @functools.wraps(func)
    def wrapper(request, *args, **kwargs):
        token = request.headers.get("Authorization")
        if not token or not validate_token(token):
            return {"error": "Unauthorized"}, 401
        return func(request, *args, **kwargs)
    return wrapper
```
